      for (const r of mixed) await r.json().catch(() => null);
      record('mixed-storm-each-order-once', ['o4', 'o5', 'o6'].every(orderId =>
        logsFor(orderId) === 1 && store.orders.get(orderId).paymentsApplied === 1));

